<style scoped lang="scss" src="./list-view.scss"></style>

<script>
import { Component, Prop, Vue } from "vue-property-decorator";
import ScrollView from "../../components/scroll-view/scroll-view";

/**
 * A Virtual List component that efficiently renders very long lists of data.
 *
 * Render list items using the renderMethod:
 *
 * ```
 * renderMethod: (h, index, style) => (
 *   <div key={index} style={style}>{index}</div>
 * );
 * ```
 */
@Component({
  components: {
    ScrollView,
  },
})
export default class ListView extends Vue {
  @Prop({ type: Boolean }) allowTouchInertia;
  @Prop({ type: Number }) scrollToOnce;
  @Prop({ type: Function, default: () => () => {} }) renderMethod;
  @Prop({ type: Number, default: 40 }) rowSize;
  @Prop({ type: Number, default: 0 }) total;
  startIndex = 0;
  endIndex = 1;

  handleScroll(scrollTop, maxScroll, viewBounds, contentBounds) {
    const { rowSize, total } = this;
    // We need to calculate the visible range of elements here. If that range changes
    // then we should trigger a re-render.
    let startIndex = Math.floor(scrollTop / rowSize) - 1;
    let endIndex = Math.floor((scrollTop + viewBounds.height) / rowSize) + 1;
    startIndex = Math.max(startIndex, 0);
    endIndex = Math.min(endIndex, total - 1);

    if (startIndex !== this.startIndex || endIndex !== this.endIndex) {
      this.$emit("range", startIndex, endIndex, total);
      this.startIndex = startIndex;
      this.endIndex = endIndex;
    }

    this.$emit("scroll", scrollTop, maxScroll, viewBounds, contentBounds);
  }

  render(h) {
    const { allowTouchInertia, rowSize, total, scrollToOnce } = this;
    const isEmpty = total <= 0;

    if (isEmpty) {
      return (
        <div class={"ListView ListView--empty"}>
          <div class="ListView__Empty">{this.$slots.default}</div>
        </div>
      );
    }

    return (
      <ScrollView
        key={"scroll-view"}
        allowTouchInertia={allowTouchInertia}
        class={"ListView"}
        scrollHeight={total * rowSize}
        scrollTopOnce={scrollToOnce}
        on={{
          scroll: this.handleScroll,
        }}
      >
        {this.renderListItems(h)}
      </ScrollView>
    );
  }

  renderListItems(h) {
    if (!this.renderMethod) return null;
    const rows = [];

    for (
      let i = this.startIndex;
      i <= Math.max(this.endIndex, this.total - 1);
      ++i
    ) {
      const style = {
        position: "absolute",
        top: `${i * this.rowSize}px`,
        left: "0px",
        width: "100%",
      };

      const row = this.renderMethod(
        h,
        i,
        style,
        i === this.endIndex || i === this.total - 1
      );

      if (!row) continue;
      rows.push(row);
    }

    return rows;
  }
}
</script>
